import React, { useEffect, useState } from 'react';
import { useForm, Controller } from 'react-hook-form';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    TextField,
    MenuItem,
    Autocomplete
} from '@mui/material';
import { IItem } from '../../Context/ItemContext';
import callApi from '../../Services/callApi';
import Swal from 'sweetalert2';
import { IDisease, IMedicine, useNurseForm } from '../../Context/NurseFormContext';

const units = ['mg', 'ml', 'tablet', 'capsule'];

interface FormData {
    no?: number
    id: number
    medicine: string;
    quantity: number;
    price: number;
    unit: string;
    total: number;
    name: string;
    disease_group: string;
    disease_group_name: string;
    symptom_id?: string;
    symptom_name?: string;
    symptom_other?: string;
}

interface Props {
    open: boolean;
    onClose: () => void;
    onOpen: () => void;
    onSubmit:(data:IMedicine)=>void;
    // onSubmit: (data: FormData) => void;
}

interface IOption {
    code: string
    label: string
}

const MedicineFormModal: React.FC<Props> = ({ open, onClose, onOpen,onSubmit }) => {
    const { medicine, setMedicine, diseaseList } = useNurseForm();
    const { register, control, handleSubmit, reset, getValues, setValue } = useForm<FormData>();
    const [medicineList, setMedicineList] = useState<IItem[]>([])
    const [diseaseOption, setDiseaseOption] = useState<any[]>([]);
    const [diseaseSelected, setDiseaseSelected] = useState<any>();
    const [symptomOption, setSymptomOption] = useState<any[]>([]);
    const [symptomOptionFiltered, setSymptomOptionFiltered] = useState<any[]>([]);
    useEffect(() => {
        onLoadItem();
        // onLoadSymptom();
        // onLoadDisease();
    }, [])
    // useEffect(() => {
    //     onDefaultDisease();
    // }, [diseaseList])

    // const onDefaultDisease = async () => {
    //     if (diseaseList[0]) {
    //         setValue('disease_group', diseaseList[0].disease_group);
    //         setValue('disease_group_name', diseaseList[0].disease_group_name);
    //     }
    // }

    const onLoadItem = async () => {
        const res = await callApi.get('/item?type=list');
        if (res.data?.data) {
            setMedicineList(res.data?.data)
        } else {
            Swal.fire('Error', res?.data.message, 'error')
        }
    }
    // const onLoadDisease = async () => {
    //     const res = await callApi.get('/disease?type=list');
    //     if (res.data?.data) {
    //         setDiseaseOption(res.data?.data)
    //     } else {
    //         Swal.fire('Error', res?.data.message, 'error')
    //     }
    // }
    // const onLoadSymptom = async () => {
    //     const res = await callApi.get('/symptom?type=list');
    //     if (res.data?.data) {
    //         setSymptomOption(res.data?.data)
    //     } else {
    //         Swal.fire('Error', res?.data.message, 'error')
    //     }
    // }

    const handleFormSubmit = (data: FormData) => {
        console.log(data)
        onSubmit(data);
        reset();
        onClose();
    };

    const handleMedicineChange = async (value: any) => {
        setValue('id', value.id)
        setValue('name', value.name)
        setValue('price', value.price)
        setValue('quantity', 1)
        setValue('total', parseFloat(value.price) * 1)
        setValue('unit', value.unit)
    }


    const handleChange = (e: any) => {
        const { value } = e.target
        var form = getValues();
        console.log(form);
        setValue('quantity', value)
        setValue('total', form.price * parseFloat(value))
    }

    return (
        <Dialog open={open} onClose={onClose}>
            <DialogTitle>บันทึกการรักษา (Treatment Record)</DialogTitle>
            <DialogContent>
                <form onSubmit={handleSubmit(handleFormSubmit)}>
                    <Autocomplete
                        fullWidth
                        options={medicineList}
                        getOptionLabel={(option) => option.id + ' | ' + option.name}
                        onChange={(_, value) => handleMedicineChange(value)}
                        renderInput={(params) => (
                            <TextField {...params} label="💊 Medicine" margin="normal" fullWidth
                                name='fullname' />
                        )}
                    />
                    <TextField
                        {...register('quantity')}
                        label="Quantity"
                        type="number"
                        fullWidth
                        margin="normal"
                        defaultValue={0}
                        onBlur={(e) => handleChange(e)}
                    />
                    <TextField
                        {...register('unit')}
                        label="Unit"
                        fullWidth
                        margin="normal"
                        disabled
                        defaultValue={'-'}
                    >
                    </TextField>
                    <TextField
                        {...register('price')}
                        label="Price"
                        type="number"
                        fullWidth
                        margin="normal"
                        disabled
                        defaultValue={0}
                    />
                    <TextField
                        {...register('total')}
                        label="Total"
                        type="number"
                        fullWidth
                        margin="normal"
                        disabled
                        defaultValue={0}
                    />
                    {/* <Autocomplete
                        {...register('disease_group')}
                        options={diseaseList}
                        getOptionLabel={(option) => option.disease_group + ' ' + option.disease_group_name}
                        onChange={(_, value: any) => handleDiseaseChange(value)}
                        renderInput={(params) => (
                            <TextField {...params} label="💊 ระบุอาการ" margin="normal"
                                // onBlur={handleChange}
                                name='disease_group' />
                        )}
                    /> */}
                    <DialogActions>
                        <Button onClick={onClose}>ยกเลิก</Button>
                        <Button type="submit" variant="contained" color="primary">
                            บันทึก
                        </Button>
                    </DialogActions>
                </form>
            </DialogContent>
        </Dialog>
    );
};

export default MedicineFormModal;
